/* GitHub clone — a repository page (Code, Issues, Pull requests, Actions) with a file browser, README, issue and
   PR lists, a pull request conversation with a comment composer, and a "Files changed" diff.
   Wide: GitHub's desktop layout with sidebars. Phone: a NavigationStack pushes folders, files and PRs. */
import { useState } from 'react';
import {
  Avatar, BLProvider, NavigationStack, TabView, TabViewBar, TabViewList, TabViewPanels, WorkbenchTheme, cn, useAppearance,
  useContainerWidth, type Screen,
} from '@brett_lamy/ui';
import { ISSUE_COUNTS, ME, PR_COUNTS, REPO } from './data';
import { Box, FlowPanel, Oct, UnderlineTab, ghButton, GITHUB_THEME, GITHUB_TINT, type OctName, type Layout, type Nav } from './parts';
import { ActionsView } from './actions-tab';
import { CodeHome, PathView } from './code-tab';
import { CloneDialog, LabelFilter } from './dialogs';
import { IssueList } from './issues-tab';
import { PullRequestView, type PullRequestTab } from './pull-request';
import { PullList } from './pulls-tab';
import { GlobalHeader, RepoHeader } from './repo-header';

export type GithubTab = 'code' | 'issues' | 'pulls' | 'actions';

export interface GithubCloneProps {
  /** Repository tab to open on. Defaults to Code. */
  initialTab?: GithubTab;
  /** Open this pull request's detail view (e.g. 488) — implies the Pull requests tab. */
  initialPullRequest?: number;
  /** Open a file or folder in the Code tab (e.g. 'src/queue.ts'). */
  initialPath?: string;
  /** The pull request's sub-tab to open on (with `initialPullRequest`), e.g. 'files' for Files changed. */
  initialPullRequestTab?: PullRequestTab;
}

export default function GithubClone({ initialTab, initialPullRequest, initialPath = '', initialPullRequestTab }: GithubCloneProps) {
  const appearance = useAppearance() === 'dark' ? 'dark' : 'light';
  const dark = appearance === 'dark';
  const [ref, width] = useContainerWidth<HTMLDivElement>(1200);
  const ui: Layout = { phone: width < 640, wide: width >= 1012, dark };
  const [tab, setTab] = useState<GithubTab>(initialTab ?? (initialPullRequest ? 'pulls' : 'code'));
  const [path, setPath] = useState(initialPath);
  const [pr, setPr] = useState<number | null>(initialPullRequest ?? null);
  const [cloneOpen, setCloneOpen] = useState(false);
  const [labelsOpen, setLabelsOpen] = useState(false);
  const [labelFilter, setLabelFilter] = useState<string[]>([]);

  const nav = {
    openPath: (p: string) => { setTab('code'); setPath(p); },
    openPr: (n: number | null) => { setTab('pulls'); setPr(n); },
    clone: () => setCloneOpen(true),
    labels: () => setLabelsOpen(true),
  };
  const page = (
    <RepoPage ui={ui} tab={tab} onTab={setTab} path={ui.phone ? '' : path} pr={ui.phone ? null : pr} nav={nav} labelFilter={labelFilter} prTab={initialPullRequestTab} />
  );

  /* Phone: the repo page is the root screen; each folder level, the open file and the PR push on top. */
  const screens: Screen[] = [
    {
      key: 'repo', title: REPO.name, content: page, hideChromeOnScroll: false,
      leading: <button type="button" aria-label="Menu" className={cn(ghButton(), 'ml-2 w-8 px-0')}><Oct name="menu" /></button>,
      trailing: <Avatar c={ME} size={28} className="mr-2.5" />,
    },
    ...(tab === 'code' && path
      ? path.split('/').map((_, i, parts) => {
          const p = parts.slice(0, i + 1).join('/');
          return { key: 'path:' + p, title: parts[i], content: <PathView ui={ui} path={p} nav={nav} />, hideChromeOnScroll: false };
        })
      : []),
    ...(tab === 'pulls' && pr ? [{ key: 'pr', title: '#' + pr, content: <PullRequestView ui={ui} number={pr} nav={nav} initialTab={initialPullRequestTab} />, hideChromeOnScroll: false }] : []),
  ];
  const pop = () => (pr && tab === 'pulls' ? setPr(null) : setPath(path.split('/').slice(0, -1).join('/')));

  return (
    <BLProvider tint={GITHUB_TINT[appearance]} style={GITHUB_THEME[appearance]} className="min-h-0 bg-background">
      <WorkbenchTheme appearance={appearance} tint={GITHUB_TINT[appearance]} style={GITHUB_THEME[appearance]}
        className="h-full w-full bg-background text-[14px] text-foreground select-text">
        <div ref={ref} className="relative flex h-full min-h-0 w-full flex-col">
          {ui.phone ? (
            <NavigationStack screens={screens} onPop={pop} />
          ) : (
            <>
              <GlobalHeader ui={ui} width={width} />
              <div className="bl-scroll min-h-0 flex-1 overflow-y-auto">{page}</div>
            </>
          )}
        </div>
        <CloneDialog open={cloneOpen} onClose={() => setCloneOpen(false)} compact={ui.phone} />
        <LabelFilter open={labelsOpen} onClose={() => setLabelsOpen(false)} compact={ui.phone} value={labelFilter} onChange={setLabelFilter} />
      </WorkbenchTheme>
    </BLProvider>
  );
}

/** Repo header + tabs; each tab shows its screen (on wide layouts the open folder / file / PR shows in place). */
function RepoPage({ ui, tab, onTab, path, pr, nav, labelFilter, prTab }: {
  ui: Layout; tab: GithubTab; onTab: (t: GithubTab) => void; path: string; pr: number | null; nav: Nav; labelFilter: string[]; prTab?: PullRequestTab;
}) {
  return (
    <TabView placement="top" selectedKey={tab} onSelectionChange={(k) => { onTab(k as GithubTab); if (k === 'pulls') nav.openPr(null); }}>
      <div className="border-b border-border">
        <RepoHeader ui={ui} />
        <TabViewBar variant="plain" className="mt-2 overflow-x-auto px-2 [scrollbar-width:none] md:px-4">
          <TabViewList aria-label="Repository" className="flex gap-1">
            <UnderlineTab id="code" icon="code" label="Code" />
            <UnderlineTab id="issues" icon="issue" label="Issues" count={ISSUE_COUNTS.open} />
            <UnderlineTab id="pulls" icon="pr" label="Pull requests" count={PR_COUNTS.open} />
            <UnderlineTab id="actions" icon="play" label="Actions" />
            {!ui.phone ? <UnderlineTab id="insights" icon="pulse" label="Insights" /> : null}
            {!ui.phone ? <UnderlineTab id="settings" icon="gear" label="Settings" /> : null}
          </TabViewList>
        </TabViewBar>
      </div>
      <TabViewPanels className="mx-auto w-full max-w-[1280px] px-4 py-6 md:px-6">
        <FlowPanel id="code">{path ? <PathView ui={ui} path={path} nav={nav} /> : <CodeHome ui={ui} nav={nav} />}</FlowPanel>
        <FlowPanel id="issues"><IssueList ui={ui} nav={nav} labelFilter={labelFilter} /></FlowPanel>
        <FlowPanel id="pulls">{pr ? <PullRequestView ui={ui} number={pr} nav={nav} initialTab={prTab} /> : <PullList ui={ui} nav={nav} />}</FlowPanel>
        <FlowPanel id="actions"><ActionsView ui={ui} /></FlowPanel>
        <FlowPanel id="insights"><Placeholder icon="pulse" title="Insights" text="Pulse, contributors, traffic and dependency graphs." /></FlowPanel>
        <FlowPanel id="settings"><Placeholder icon="gear" title="Settings" text="Only repository admins can change settings." /></FlowPanel>
      </TabViewPanels>
    </TabView>
  );
}

function Placeholder({ icon, title, text }: { icon: OctName; title: string; text: string }) {
  return (
    <Box className="grid place-items-center px-6 py-16 text-center">
      <Oct name={icon} size={24} className="text-muted-foreground" />
      <h3 className="mt-3 mb-1 text-[20px] font-semibold">{title}</h3>
      <p className="m-0 text-muted-foreground">{text}</p>
    </Box>
  );
}

/* The site header (desktop) and the repository header: owner / name, visibility, Watch / Fork / Star. */
import { Avatar, Badge, Button, cn } from '@brett_lamy/ui';
import { ME, REPO } from './data';
import { Counter, Mark, Oct, ghButton, type OctName, type Layout } from './parts';

export function GlobalHeader({ ui, width }: { ui: Layout; width: number }) {
  return (
    <header className="flex h-16 shrink-0 items-center gap-3 border-b border-border bg-[var(--gh-inset)] px-4">
      <button type="button" aria-label="Open menu" className={cn(ghButton(), 'w-8 bg-transparent px-0')}><Oct name="menu" /></button>
      <Mark />
      <nav className="flex min-w-0 items-center gap-1 text-[14px]">
        <span className="rounded-md px-1.5 py-1 hover:bg-secondary">{REPO.owner}</span>
        <span className="text-tertiary-foreground">/</span>
        <span className="truncate rounded-md px-1.5 py-1 font-semibold hover:bg-secondary">{REPO.name}</span>
      </nav>
      <span className="flex-1" />
      {width >= 900 ? (
        <div className="flex h-8 w-[300px] items-center gap-2 rounded-md border border-border bg-background px-2 text-muted-foreground">
          <Oct name="search" />
          <span className="flex-1">Type <kbd className="rounded border border-border px-1 font-mono text-[11px]">/</kbd> to search</span>
        </div>
      ) : null}
      {ui.wide ? <span className="h-5 w-px bg-border" /> : null}
      <button type="button" aria-label="Create new" className={cn(ghButton(), 'gap-1 bg-transparent px-2 text-muted-foreground')}>
        <Oct name="plus" /><Oct name="chevDown" size={12} />
      </button>
      {(['issue', 'pr', 'inbox'] as OctName[]).map((n) => (
        <button key={n} type="button" aria-label={n} className={cn(ghButton(), 'w-8 bg-transparent px-0 text-muted-foreground')}><Oct name={n} /></button>
      ))}
      <Avatar c={ME} size={32} />
    </header>
  );
}

export function RepoHeader({ ui }: { ui: Layout }) {
  const counted = (icon: OctName, label: string, count: string) => (
    <div className="flex">
      <Button className={cn(ghButton(), 'rounded-r-none')}><Oct name={icon} className="text-muted-foreground" />{label}<Counter>{count}</Counter></Button>
      <Button aria-label={label + ' options'} className={cn(ghButton(), '-ml-px rounded-l-none px-2')}><Oct name="chevDown" size={12} /></Button>
    </div>
  );
  return (
    <div className="px-4 pt-4 md:px-6">
      <div className="flex flex-wrap items-center gap-x-3 gap-y-3">
        <div className="flex min-w-0 items-center gap-2 text-[20px]">
          <Oct name="book" className="text-muted-foreground" />
          <span className="text-primary">{REPO.owner}</span>
          <span className="text-tertiary-foreground">/</span>
          <strong className="truncate font-semibold text-primary">{REPO.name}</strong>
          <Badge variant="outline" className="h-5 px-2 text-[12px] font-medium text-muted-foreground">Public</Badge>
        </div>
        {!ui.phone ? (
          <div className="ml-auto flex flex-wrap gap-2">
            {counted('eye', 'Watch', REPO.watchers)}
            {counted('fork', 'Fork', REPO.forks)}
            {counted('star', 'Star', REPO.stars)}
          </div>
        ) : null}
      </div>
      {!ui.wide ? (
        <div className="mt-3 space-y-3">
          <p className="m-0 text-[14px] leading-5 text-muted-foreground">{REPO.description}</p>
          <div className="flex flex-wrap items-center gap-x-4 gap-y-1 text-[14px] text-muted-foreground">
            <span className="flex items-center gap-1.5 font-semibold text-primary"><Oct name="link" />{REPO.homepage}</span>
            <span className="flex items-center gap-1.5"><Oct name="star" /><b className="text-foreground">{REPO.stars}</b> stars</span>
            <span className="flex items-center gap-1.5"><Oct name="fork" /><b className="text-foreground">{REPO.forks}</b> forks</span>
          </div>
          {ui.phone ? (
            <div className="flex gap-2">
              <Button className={cn(ghButton(), 'flex-1')}><Oct name="star" className="text-muted-foreground" />Star</Button>
              <Button className={cn(ghButton(), 'flex-1')}><Oct name="eye" className="text-muted-foreground" />Watch</Button>
              <Button className={cn(ghButton(), 'flex-1')}><Oct name="fork" className="text-muted-foreground" />Fork</Button>
            </div>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

/* Code tab: branch toolbar, file table, README and About sidebar; folders and files with GitHub's file-tree sidebar. */
import { useState, type ReactNode } from 'react';
import { Avatar, Button, DropdownMenu, DropdownMenuContent, DropdownMenuItem, MarkdownView, Segmented, SyntaxHighlightingCopyButton, cn } from '@brett_lamy/ui';
import { README_MD, REPO, TREE, findNode, type FileNode } from './data';
import { Box, CodeView, Counter, FileTree, Oct, ghButton, githubMarkdown, type OctName, type Layout, type Nav } from './parts';

export function CodeHome({ ui, nav }: { ui: Layout; nav: Nav }) {
  return (
    <div className="flex gap-6">
      <div className="min-w-0 flex-1 space-y-4">
        <CodeToolbar ui={ui} nav={nav} />
        <FileTable ui={ui} nodes={TREE} nav={nav} />
        <Box header={
          <div className="-my-2 flex items-center gap-4 self-stretch">
            <span className="relative flex h-full items-center gap-2 font-semibold after:absolute after:inset-x-0 after:-bottom-px after:h-0.5 after:rounded-full after:bg-[var(--gh-tab)]">
              <Oct name="book" className="text-muted-foreground" />README
            </span>
            <span className="flex items-center gap-2 text-muted-foreground"><Oct name="law" />{REPO.license}</span>
          </div>
        }>
          <Readme markdown={README_MD} phone={ui.phone} />
        </Box>
      </div>
      {ui.wide ? <About /> : null}
    </div>
  );
}

export function Readme({ markdown, phone }: { markdown: string; phone: boolean }) {
  return (
    <MarkdownView markdown={markdown}
      className={cn(githubMarkdown, 'text-[16px] leading-[1.5] [&_table]:text-[14px]', phone ? 'px-4 py-5' : 'px-8 py-6')} />
  );
}

export function CodeToolbar({ ui, nav }: { ui: Layout; nav: Nav }) {
  const [branch, setBranch] = useState(REPO.branch);
  return (
    <div className="flex items-center gap-2">
      <DropdownMenu>
        <Button className={ghButton()}><Oct name="branch" className="text-muted-foreground" /><span className="max-w-[140px] truncate">{branch}</span><Oct name="chevDown" size={12} className="text-muted-foreground" /></Button>
        <DropdownMenuContent aria-label="Switch branches" selectionMode="single" selectedKeys={[branch]}
          onSelectionChange={(keys) => setBranch(String([...(keys as Set<string>)][0] ?? branch))} className="py-1">
          {REPO.branches.map((b) => (
            <DropdownMenuItem key={b} id={b} className="min-h-9 py-1.5 font-mono text-[13px]">{b}</DropdownMenuItem>
          ))}
        </DropdownMenuContent>
      </DropdownMenu>
      {!ui.phone ? (
        <>
          <span className="flex items-center gap-1.5 px-2 text-muted-foreground"><Oct name="branch" /><b className="text-foreground">{REPO.branchCount}</b> Branches</span>
          <span className="flex items-center gap-1.5 px-2 text-muted-foreground"><Oct name="tag" /><b className="text-foreground">{REPO.tagCount}</b> Tags</span>
        </>
      ) : null}
      <span className="flex-1" />
      {ui.wide ? (
        <div className="flex h-8 w-[240px] items-center gap-2 rounded-md border border-border px-2 text-muted-foreground">
          <Oct name="search" /><span className="flex-1">Go to file</span><kbd className="rounded border border-border px-1 font-mono text-[11px]">t</kbd>
        </div>
      ) : null}
      {!ui.phone ? <Button className={ghButton()}>Add file<Oct name="chevDown" size={12} /></Button> : null}
      <Button className={ghButton(true)} onPress={nav.clone}><Oct name="code" />Code<Oct name="chevDown" size={12} /></Button>
    </div>
  );
}

export function LastCommit({ ui, message = REPO.lastCommit.message, when = REPO.lastCommit.when }: { ui: Layout; message?: string; when?: string }) {
  const c = REPO.lastCommit;
  return (
    <div className="flex w-full min-w-0 items-center gap-2">
      <Avatar c={c.author} size={24} />
      <b className="shrink-0 font-semibold">{c.author.login}</b>
      <span className="min-w-0 truncate text-muted-foreground">{message}</span>
      <span className="flex-1" />
      {!ui.phone ? <span className="shrink-0 font-mono text-[12px] text-muted-foreground">{c.sha} · {when}</span> : null}
      <span className="flex shrink-0 items-center gap-1.5 font-semibold"><Oct name="history" className="text-muted-foreground" />{ui.phone ? '' : REPO.commitCount + ' Commits'}</span>
    </div>
  );
}

export function FileTable({ ui, nodes, nav, parent }: { ui: Layout; nodes: FileNode[]; nav: Nav; parent?: string }) {
  const sorted = [...nodes].sort((a, b) => (a.type === b.type ? a.name.localeCompare(b.name) : a.type === 'dir' ? -1 : 1));
  return (
    <Box header={<LastCommit ui={ui} />}>
      {parent != null ? (
        <FileRow ui={ui} icon={<Oct name="folder" className="text-[var(--gh-folder)]" />} name=".." onOpen={() => nav.openPath(parent)} />
      ) : null}
      {sorted.map((n) => (
        <FileRow key={n.path} ui={ui} name={n.name} commit={n.commit} when={n.when} onOpen={() => nav.openPath(n.path)}
          icon={n.type === 'dir' ? <Oct name="folder" className="text-[var(--gh-folder)]" /> : <Oct name="file" className="text-muted-foreground" />} />
      ))}
    </Box>
  );
}

export function FileRow({ ui, icon, name, commit, when, onOpen }: { ui: Layout; icon: ReactNode; name: string; commit?: string; when?: string; onOpen: () => void }) {
  return (
    <div className="flex h-10 items-center gap-3 border-t border-border px-4 first:border-t-0 hover:bg-muted">
      {icon}
      <button type="button" onClick={onOpen}
        className={cn('min-w-0 cursor-pointer truncate border-0 bg-transparent p-0 text-left text-[14px] text-foreground hover:text-primary hover:underline', ui.phone ? 'flex-1' : 'w-[34%] shrink-0')}>
        {name}
      </button>
      {!ui.phone ? <span className="min-w-0 flex-1 truncate text-muted-foreground">{commit}</span> : null}
      <span className="shrink-0 text-right text-muted-foreground">{when}</span>
    </div>
  );
}

export function About() {
  const section = 'border-b border-border py-6 first:pt-0 last:border-0';
  return (
    <aside className="w-[296px] shrink-0 text-[14px]">
      <div className={section}>
        <h2 className="mt-0 mb-4 text-[16px] font-semibold">About</h2>
        <p className="m-0 text-[16px] leading-6">{REPO.description}</p>
        <p className="my-4 flex items-center gap-2 font-semibold text-primary"><Oct name="link" className="text-muted-foreground" />{REPO.homepage}</p>
        <div className="flex flex-wrap gap-1.5">
          {REPO.topics.map((t) => (
            <span key={t} className="rounded-full bg-primary/10 px-2.5 py-[3px] text-[12px] leading-[18px] font-medium text-primary">{t}</span>
          ))}
        </div>
        <ul className="mt-4 mb-0 list-none space-y-2 p-0 text-muted-foreground">
          {([['book', 'Readme'], ['law', REPO.license], ['pulse', 'Activity'], ['star', REPO.stars + ' stars'], ['eye', REPO.watchers + ' watching'], ['fork', REPO.forks + ' forks']] as [OctName, string][]).map(([i, t]) => (
            <li key={t} className="flex items-center gap-2 hover:text-primary"><Oct name={i} />{t}</li>
          ))}
        </ul>
      </div>
      <div className={section}>
        <h2 className="mt-0 mb-3 flex items-center gap-2 text-[16px] font-semibold">Releases <Counter>{REPO.release.count}</Counter></h2>
        <div className="flex gap-2">
          <Oct name="tag" className="mt-0.5 text-[var(--gh-open)]" />
          <div>
            <div className="flex items-center gap-2"><b className="font-semibold">{REPO.release.tag}</b>
              <span className="rounded-full border border-[var(--gh-open)] px-2 text-[12px] leading-[18px] font-medium text-[var(--gh-open)]">Latest</span></div>
            <div className="text-[12px] text-muted-foreground">{REPO.release.when}</div>
          </div>
        </div>
      </div>
      <div className={section}>
        <h2 className="mt-0 mb-3 flex items-center gap-2 text-[16px] font-semibold">Contributors <Counter>{REPO.contributorCount}</Counter></h2>
        <div className="flex flex-wrap gap-1">{REPO.contributors.map((u) => <Avatar key={u.login} c={u} size={32} />)}</div>
      </div>
      <div className={section}>
        <h2 className="mt-0 mb-3 text-[16px] font-semibold">Languages</h2>
        <div className="flex h-2 gap-0.5 overflow-hidden rounded-full">
          {REPO.languages.map((l) => <span key={l.name} style={{ width: l.pct + '%', background: l.color }} />)}
        </div>
        <ul className="mt-3 mb-0 flex list-none flex-wrap gap-x-4 gap-y-1 p-0 text-[12px]">
          {REPO.languages.map((l) => (
            <li key={l.name} className="flex items-center gap-1.5">
              <span className="size-2 rounded-full" style={{ background: l.color }} /><b className="font-semibold">{l.name}</b><span className="text-muted-foreground">{l.pct}%</span>
            </li>
          ))}
        </ul>
      </div>
    </aside>
  );
}

/** A folder listing or a file viewer, with GitHub's file-tree sidebar at wide widths. */
export function PathView({ ui, path, nav }: { ui: Layout; path: string; nav: Nav }) {
  const node = findNode(path);
  const parts = path.split('/');
  if (!node) return null;
  const crumbs = (
    <div className="flex min-w-0 flex-wrap items-center gap-1 text-[16px]">
      <button type="button" onClick={() => nav.openPath('')} className="cursor-pointer border-0 bg-transparent p-0 text-[16px] font-semibold text-primary hover:underline">{REPO.name}</button>
      {parts.map((p, i) => (
        <span key={i} className="flex items-center gap-1">
          <span className="text-tertiary-foreground">/</span>
          {i === parts.length - 1
            ? <b className="font-semibold">{p}</b>
            : <button type="button" onClick={() => nav.openPath(parts.slice(0, i + 1).join('/'))} className="cursor-pointer border-0 bg-transparent p-0 text-[16px] text-primary hover:underline">{p}</button>}
        </span>
      ))}
      <Oct name="copy" size={14} className="ml-1 text-muted-foreground" />
    </div>
  );
  return (
    <div className={cn('flex gap-6', ui.phone && 'px-4 py-4')}>
      {ui.wide ? (
        <aside className="w-[280px] shrink-0 border-r border-border pr-4">
          <div className="mb-3 flex items-center gap-2">
            <Oct name="sidebar" className="text-muted-foreground" /><b className="text-[16px] font-semibold">Files</b>
          </div>
          <div className="mb-3 flex h-8 items-center gap-2 rounded-md border border-border px-2 text-muted-foreground"><Oct name="search" />Go to file</div>
          <FileTree nodes={TREE} selected={path} onSelect={(n) => nav.openPath(n.path)} />
        </aside>
      ) : null}
      <div className="min-w-0 flex-1 space-y-4">
        {!ui.phone ? crumbs : null}
        {node.type === 'dir' ? (
          <FileTable ui={ui} nodes={node.children ?? []} nav={nav} parent={parts.slice(0, -1).join('/')} />
        ) : (
          <>
            <Box className="px-4 py-3"><LastCommit ui={ui} message={node.commit} when={node.when} /></Box>
            <FileViewer ui={ui} node={node} />
          </>
        )}
      </div>
    </div>
  );
}

export function FileViewer({ ui, node }: { ui: Layout; node: FileNode }) {
  const code = node.content ?? `// ${node.name}\n// Contents are not included in this sample repository.\n`;
  const isMd = node.name.endsWith('.md') && node.content;
  const [view, setView] = useState(isMd ? 'preview' : 'code');
  const lines = code.replace(/\n$/, '').split('\n').length;
  return (
    <Box header={
      <div className="flex w-full items-center gap-3">
        <Segmented aria-label="View" value={view} onChange={setView} className="w-[150px] rounded-md"
          options={isMd ? [{ id: 'preview', label: 'Preview' }, { id: 'code', label: 'Code' }] : [{ id: 'code', label: 'Code' }, { id: 'blame', label: 'Blame' }]} />
        {!ui.phone ? <span className="text-[12px] text-muted-foreground">{lines} lines · {(code.length / 1024).toFixed(1)} KB</span> : null}
        <span className="flex-1" />
        <Button className={cn(ghButton(), 'h-7 px-2.5 text-[12px]')}>Raw</Button>
        <SyntaxHighlightingCopyButton value={code} label="Copy raw file" className={cn(ghButton(), 'h-7 w-7 px-0')} />
      </div>
    }>
      {view === 'preview' ? <Readme markdown={code} phone={ui.phone} /> : <CodeView path={node.path} code={code} />}
    </Box>
  );
}

/* Issues tab: search, label filter, Open/Closed and the issue rows. */
import { useState } from 'react';
import { ISSUES, ISSUE_COUNTS, LABELS } from './data';
import { Box, LabelChip, Oct, type Layout, type Nav } from './parts';
import { FilterMenus, ItemRow, ListToolbar, StateToggle } from './lists';

export function IssueList({ ui, nav, labelFilter }: { ui: Layout; nav: Nav; labelFilter: string[] }) {
  const [state, setState] = useState<'open' | 'closed'>('open');
  const [q, setQ] = useState('');
  const rows = ISSUES.filter((i) => i.state === state)
    .filter((i) => !q || i.title.toLowerCase().includes(q.toLowerCase()))
    .filter((i) => labelFilter.every((l) => i.labels.some((x) => x.name === l)));
  return (
    <div>
      <ListToolbar ui={ui} nav={nav} q={q} setQ={setQ} placeholder={`is:issue state:${state}`} newLabel="New issue" />
      {labelFilter.length ? (
        <div className="mb-3 flex flex-wrap items-center gap-1.5 text-muted-foreground">
          Filtered by {labelFilter.map((l) => <LabelChip key={l} label={Object.values(LABELS).find((x) => x.name === l)!} dark={ui.dark} />)}
        </div>
      ) : null}
      <Box header={
        <>
          <StateToggle value={state} onChange={setState} open={ISSUE_COUNTS.open} closed={ISSUE_COUNTS.closed} closedIcon="check" />
          <FilterMenus ui={ui} names={['Author', 'Labels', 'Projects', 'Milestones', 'Assignee', 'Sort']} onLabel={nav.labels} />
        </>
      }>
        {rows.map((i) => (
          <ItemRow key={i.number} ui={ui} state={i.state === 'open' ? 'open' : 'closed'} title={i.title} labels={i.labels}
            meta={<>#{i.number} {i.state === 'open' ? 'opened' : 'was closed'} {i.when} by {i.author.login}{i.milestone ? <span className="ml-2 inline-flex items-center gap-1"><Oct name="history" size={12} />{i.milestone}</span> : null}</>}
            assignees={i.assignees} comments={i.comments} />
        ))}
        {rows.length === 0 ? <div className="px-4 py-10 text-center text-muted-foreground">No results matched your search.</div> : null}
      </Box>
      <p className="mt-4 text-center text-[12px] text-muted-foreground">
        <b className="font-semibold">ProTip!</b> Add <code className="rounded bg-secondary px-1 font-mono">no:assignee</code> to see everything that’s not assigned.
      </p>
    </div>
  );
}

/* Pull requests tab: the PR list with check status and review state. */
import { useState } from 'react';
import { PR_COUNTS, PULLS } from './data';
import { Box, Oct, PR_STATE, type Layout, type Nav } from './parts';
import { FilterMenus, ItemRow, ListToolbar, StateToggle } from './lists';

export const CHECK_ICON = {
  success: <Oct name="check" className="text-[var(--gh-open)]" />,
  failure: <Oct name="x" className="text-[var(--gh-closed)]" />,
  pending: <span className="mx-1 size-2 rounded-full bg-[var(--gh-attention)]" />,
};
export const REVIEW_TEXT = { approved: 'Approved', changes: 'Changes requested', pending: 'Review required', draft: 'Draft' };

export function PullList({ ui, nav }: { ui: Layout; nav: Nav }) {
  const [state, setState] = useState<'open' | 'closed'>('open');
  const [q, setQ] = useState('');
  const rows = PULLS.filter((p) => (state === 'open' ? p.state === 'open' || p.state === 'draft' : p.state === 'merged' || p.state === 'closed'))
    .filter((p) => !q || p.title.toLowerCase().includes(q.toLowerCase()));
  return (
    <div>
      <ListToolbar ui={ui} nav={nav} q={q} setQ={setQ} placeholder={`is:pr state:${state}`} newLabel="New pull request" />
      <Box header={
        <>
          <StateToggle value={state} onChange={setState} open={PR_COUNTS.open} closed={PR_COUNTS.closed} closedIcon="check" />
          <FilterMenus ui={ui} names={['Author', 'Labels', 'Projects', 'Milestones', 'Reviews', 'Assignee', 'Sort']} onLabel={nav.labels} />
        </>
      }>
        {rows.map((p) => (
          <ItemRow key={p.number} ui={ui} state={PR_STATE[p.state]} title={p.title} labels={p.labels} status={CHECK_ICON[p.checks]}
            onOpen={() => nav.openPr(p.number)} assignees={[p.author]} comments={p.comments}
            meta={<>#{p.number} {p.state === 'merged' ? 'merged' : 'opened'} {p.when} by {p.author.login} · <span className={p.review === 'approved' ? 'text-[var(--gh-open)]' : p.review === 'changes' ? 'text-[var(--gh-closed)]' : ''}>{REVIEW_TEXT[p.review]}</span></>} />
        ))}
      </Box>
    </div>
  );
}

/* Shared pieces of the Issues and Pull requests lists: search toolbar, Open/Closed toggle, filter menus, rows. */
import { type ReactNode } from 'react';
import { Button, SearchField, cn } from '@brett_lamy/ui';
import { LABELS, type Label } from './data';
import { AvatarStack, Counter, LabelChip, Oct, StateIcon, ghButton, type OctName, type StateKind, type Layout, type Nav } from './parts';

export function ListToolbar({ ui, nav, q, setQ, placeholder, newLabel }: { ui: Layout; nav: Nav; q: string; setQ: (q: string) => void; placeholder: string; newLabel: string }) {
  return (
    <div className="mb-4 flex flex-wrap items-center gap-2">
      <SearchField value={q} onChange={setQ} placeholder={placeholder} aria-label="Search"
        className="h-8 min-w-[200px] flex-1 rounded-md border border-border bg-muted px-2 py-0 text-[14px] [&_input]:text-[14px] [&_svg]:size-4" />
      <div className="flex">
        <Button className={cn(ghButton(), 'rounded-r-none')} onPress={nav.labels}><Oct name="tag" className="text-muted-foreground" />Labels{!ui.phone ? <Counter>{Object.keys(LABELS).length}</Counter> : null}</Button>
        <Button className={cn(ghButton(), '-ml-px rounded-l-none')}><Oct name="history" className="text-muted-foreground" />Milestones</Button>
      </div>
      <Button className={ghButton(true)}>{newLabel}</Button>
    </div>
  );
}

export function StateToggle({ value, onChange, open, closed, closedIcon }: {
  value: 'open' | 'closed'; onChange: (v: 'open' | 'closed') => void; open: number; closed: number; closedIcon: OctName;
}) {
  const item = (v: 'open' | 'closed', icon: OctName, n: number, label: string) => (
    <button type="button" onClick={() => onChange(v)} aria-pressed={value === v}
      className={cn('flex cursor-pointer items-center gap-1.5 rounded-md border-0 bg-transparent px-2 py-1 text-[14px] hover:bg-secondary',
        value === v ? 'font-semibold text-foreground' : 'text-muted-foreground')}>
      <Oct name={icon} />{n} {label}
    </button>
  );
  return <div className="flex items-center gap-1">{item('open', 'issue', open, 'Open')}{item('closed', closedIcon, closed, 'Closed')}</div>;
}

export function FilterMenus({ ui, names, onLabel }: { ui: Layout; names: string[]; onLabel: () => void }) {
  if (ui.phone) return null;
  const shown = ui.wide ? names : names.slice(-2);
  return (
    <div className="ml-auto flex items-center text-muted-foreground">
      {shown.map((n) => (
        <button key={n} type="button" onClick={n === 'Labels' ? onLabel : undefined}
          className="flex cursor-pointer items-center gap-1 rounded-md border-0 bg-transparent px-2 py-1 text-[14px] text-muted-foreground hover:bg-secondary hover:text-foreground">
          {n}<Oct name="chevDown" size={12} />
        </button>
      ))}
    </div>
  );
}

export function ItemRow({ ui, state, title, labels, meta, assignees, comments, status, onOpen }: {
  ui: Layout; state: StateKind; title: string; labels: Label[]; meta: ReactNode; assignees: { login: string; f: string; l: string }[];
  comments: number; status?: ReactNode; onOpen?: () => void;
}) {
  return (
    <div className="flex gap-2 border-t border-border px-4 py-2 first:border-t-0 hover:bg-muted">
      <StateIcon state={state} className="mt-[3px]" />
      <div className="min-w-0 flex-1">
        <div className="flex flex-wrap items-center gap-x-1.5 gap-y-1">
          <button type="button" onClick={onOpen}
            className="cursor-pointer border-0 bg-transparent p-0 text-left text-[16px] leading-6 font-semibold text-foreground hover:text-primary">
            {title}
          </button>
          {status}
          {labels.map((l) => <LabelChip key={l.name} label={l} dark={ui.dark} />)}
        </div>
        <div className="mt-1 text-[12px] text-muted-foreground">{meta}</div>
      </div>
      {!ui.phone ? (
        <div className="flex w-[120px] shrink-0 items-start justify-end gap-4 pt-1">
          {assignees.length ? <AvatarStack users={assignees} /> : null}
          {comments ? <span className="flex items-center gap-1 text-[12px] text-muted-foreground hover:text-primary"><Oct name="comment" />{comments}</span> : null}
        </div>
      ) : comments ? (
        <span className="flex shrink-0 items-center gap-1 pt-1 text-[12px] text-muted-foreground"><Oct name="comment" size={14} />{comments}</span>
      ) : null}
    </div>
  );
}

/* A pull request: title and state, then Conversation (timeline, merge box, comment composer), Commits, Checks and
   Files changed. */
import { useState, type ReactNode } from 'react';
import {
  Avatar, Button, Composer, ComposerCard, ComposerFooter, ComposerInput, ComposerSend, ComposerSpacer, ComposerText, MarkdownView, Progress, TabView, TabViewBar, TabViewFooter, TabViewList, TabViewPanels, cn,
} from '@brett_lamy/ui';
import { ME, PR_CHECKS, PR_COMMITS, PR_FILES, PR_TIMELINE, PULLS, USERS, type FileNode, type PullRequest, type TimelineItem } from './data';
import { AvatarStack, Box, DiffStat, DiffView, FileTree, FlowPanel, LabelChip, Oct, StatePill, UnderlineTab, ghButton, githubMarkdown, Branch, PR_STATE, type OctName, type Layout, type Nav } from './parts';

export type PullRequestTab = 'conversation' | 'commits' | 'checks' | 'files';

export function PullRequestView({ ui, number, nav, initialTab = 'conversation' }: { ui: Layout; number: number; nav: Nav; initialTab?: PullRequestTab }) {
  const p = PULLS.find((x) => x.number === number) ?? PULLS[0];
  const [sub, setSub] = useState<string>(initialTab);
  return (
    <div className={cn(ui.phone && 'px-4 py-4')}>
      {!ui.phone ? (
        <button type="button" onClick={() => nav.openPr(null)} className="mb-3 flex cursor-pointer items-center gap-1 border-0 bg-transparent p-0 text-[14px] text-primary hover:underline">
          <Oct name="chevLeft" size={14} />Pull requests
        </button>
      ) : null}
      <div className="flex items-start gap-4">
        <h1 className={cn('m-0 min-w-0 flex-1 leading-tight font-normal', ui.phone ? 'text-[22px]' : 'text-[32px]')}>
          {p.title} <span className="font-light text-muted-foreground">#{p.number}</span>
        </h1>
        {!ui.phone ? (
          <div className="flex shrink-0 gap-2 pt-1.5">
            <Button className={ghButton()}>Edit</Button>
            <Button className={ghButton(true)} onPress={nav.clone}><Oct name="code" />Code<Oct name="chevDown" size={12} /></Button>
          </div>
        ) : null}
      </div>
      <div className="mt-3 flex flex-wrap items-center gap-x-2 gap-y-2 border-b border-border pb-4 text-muted-foreground">
        <StatePill state={PR_STATE[p.state]} />
        <span className="leading-6">
          <b className="font-semibold text-foreground">{p.author.login}</b> wants to merge {p.commits} commits into <Branch>{p.base}</Branch> from <Branch>{p.head}</Branch>
        </span>
      </div>
      <TabView placement="top" selectedKey={sub} onSelectionChange={(k) => setSub(String(k))} className="mt-2">
        <TabViewBar variant="plain" className="overflow-x-auto border-b border-border [scrollbar-width:none]">
          <TabViewList aria-label="Pull request" className="flex gap-1">
            <UnderlineTab id="conversation" icon="comment" label="Conversation" count={p.comments} />
            <UnderlineTab id="commits" icon="commit" label="Commits" count={PR_COMMITS.length} />
            <UnderlineTab id="checks" icon="checkFill" label="Checks" count={PR_CHECKS.length} />
            <UnderlineTab id="files" icon="file" label="Files changed" count={PR_FILES.length} />
          </TabViewList>
          {!ui.phone ? <TabViewFooter className="pl-4"><DiffStat add={p.additions} del={p.deletions} /></TabViewFooter> : null}
        </TabViewBar>
        <TabViewPanels className="pt-6">
          <FlowPanel id="conversation"><Conversation ui={ui} pr={p} /></FlowPanel>
          <FlowPanel id="commits"><CommitList ui={ui} /></FlowPanel>
          <FlowPanel id="checks"><Checks /></FlowPanel>
          <FlowPanel id="files"><FilesChanged ui={ui} /></FlowPanel>
        </TabViewPanels>
      </TabView>
    </div>
  );
}

/* ── Conversation ── */

export function Conversation({ ui, pr }: { ui: Layout; pr: PullRequest }) {
  const [items, setItems] = useState<TimelineItem[]>(PR_TIMELINE);
  const comment = (body: string) =>
    setItems((xs) => [...xs, { kind: 'comment', id: 'new' + xs.length, author: ME, when: 'now', body, role: 'Member' }]);
  const side = 'border-b border-border py-4 text-[12px] first:pt-0';
  const sideTitle = 'mb-2 flex items-center justify-between font-semibold text-muted-foreground';
  return (
    <div className="flex gap-6">
      <div className="min-w-0 flex-1">
        {/* The timeline rail runs behind the event badges. */}
        <div className={cn('relative', ui.phone ? 'before:left-4' : 'before:left-[72px]', 'before:absolute before:inset-y-0 before:w-0.5 before:bg-border')}>
          {items.map((it) => <TimelineEntry key={it.id} ui={ui} item={it} />)}
        </div>
        <MergeBox ui={ui} />
        <div className="mt-6 flex gap-4 border-t-2 border-border pt-6">
          {!ui.phone ? <Avatar c={ME} size={40} /> : null}
          <div className="min-w-0 flex-1">
            <h3 className="mt-0 mb-2 text-[14px] font-semibold">Add a comment</h3>
            <Composer onSubmit={comment}>
              <ComposerCard className="rounded-md shadow-none">
                <ComposerInput placeholder="Use Markdown to format your comment" slashMenu={false} />
                <ComposerFooter>
                  <ComposerText><Oct name="book" size={14} />Markdown is supported</ComposerText>
                  <ComposerSpacer />
                  <ComposerSend />
                </ComposerFooter>
              </ComposerCard>
            </Composer>
            <div className="mt-3 flex justify-end gap-2">
              <Button className={ghButton()}><Oct name="prClosed" className="text-[var(--gh-closed)]" />Close pull request</Button>
            </div>
          </div>
        </div>
      </div>
      {ui.wide ? (
        <aside className="w-[256px] shrink-0">
          <div className={side}>
            <div className={sideTitle}>Reviewers<Oct name="gear" size={14} /></div>
            <div className="flex items-center gap-2"><Avatar c={USERS.jonas} size={20} /><b className="flex-1 font-semibold">{USERS.jonas.login}</b><Oct name="check" className="text-[var(--gh-open)]" /></div>
          </div>
          <div className={side}>
            <div className={sideTitle}>Assignees<Oct name="gear" size={14} /></div>
            <div className="flex items-center gap-2"><Avatar c={pr.author} size={20} /><b className="font-semibold">{pr.author.login}</b></div>
          </div>
          <div className={side}>
            <div className={sideTitle}>Labels<Oct name="gear" size={14} /></div>
            <div className="flex flex-wrap gap-1">{pr.labels.map((l) => <LabelChip key={l.name} label={l} dark={ui.dark} />)}</div>
          </div>
          <div className={side}>
            <div className={sideTitle}>Milestone<Oct name="gear" size={14} /></div>
            <Progress aria-label="v3.3 progress" value={62} size="sm" tone="success" />
            <b className="mt-1.5 block font-semibold">v3.3</b>
          </div>
          <div className={side}>
            <div className={sideTitle}>Development</div>
            <p className="m-0 text-muted-foreground">Successfully merging this pull request may close these issues.</p>
            <p className="mt-2 mb-0 flex items-center gap-1.5"><Oct name="issue" size={14} className="text-[var(--gh-open)]" /><b className="font-semibold">Retries fire in lockstep after an outage</b></p>
          </div>
          <div className={side}>
            <div className={sideTitle}>Participants</div>
            <AvatarStack users={[USERS.maya, USERS.jonas, USERS.priya]} size={26} />
          </div>
        </aside>
      ) : null}
    </div>
  );
}

export function CommentCard({ ui, author, when, body, role, verb = 'commented', tone }: {
  ui: Layout; author: { login: string; f: string; l: string }; when: string; body: string; role?: string; verb?: string; tone?: 'author';
}) {
  return (
    <div className="relative flex gap-4 py-4">
      {!ui.phone ? <Avatar c={author} size={40} /> : null}
      <div className={cn('relative z-1 min-w-0 flex-1 overflow-hidden rounded-md border bg-background', tone === 'author' ? 'border-primary/40' : 'border-border')}>
        <div className={cn('flex items-center gap-1.5 border-b px-4 py-2 text-muted-foreground', tone === 'author' ? 'border-primary/40 bg-primary/8' : 'border-border bg-muted')}>
          {ui.phone ? <Avatar c={author} size={20} /> : null}
          <b className="shrink-0 font-semibold whitespace-nowrap text-foreground">{author.login}</b>
          <span className="min-w-0 truncate">{verb} {when}</span>
          <span className="flex-1" />
          {role && !ui.phone ? <span className="rounded-full border border-border px-2 text-[12px] leading-[18px] font-medium">{role}</span> : null}
          <Oct name="kebab" className="shrink-0" />
        </div>
        <MarkdownView markdown={body} className={cn(githubMarkdown, 'bg-background px-4 py-3 text-[14px] leading-[1.5]')} />
      </div>
    </div>
  );
}

export function TimelineEvent({ ui, icon, badge, children }: { ui: Layout; icon: OctName; badge?: string; children: ReactNode }) {
  return (
    <div className={cn('relative flex items-start gap-2 py-3', ui.phone ? 'pl-0' : 'pl-14')}>
      <span className={cn('z-1 grid size-8 shrink-0 place-items-center rounded-full border-2 border-background', badge ?? 'bg-muted text-muted-foreground')}>
        <Oct name={icon} size={16} />
      </span>
      <div className="min-w-0 flex-1 pt-1.5 text-muted-foreground">{children}</div>
    </div>
  );
}

export function TimelineEntry({ ui, item }: { ui: Layout; item: TimelineItem }) {
  const who = (u: { login: string; f: string; l: string }) => (
    <><Avatar c={u} size={20} className="mr-1.5 inline-grid align-[-5px]" /><b className="font-semibold text-foreground">{u.login}</b></>
  );
  switch (item.kind) {
    case 'comment':
      return <CommentCard ui={ui} author={item.author} when={item.when} body={item.body} role={item.role} tone={item.author.login === 'maya-chen' ? 'author' : undefined} />;
    case 'commits':
      return (
        <TimelineEvent ui={ui} icon="commit">
          {who(item.author)} added {item.commits.length} commits {item.when}
          <ul className="mt-2 mb-0 list-none space-y-1.5 p-0">
            {item.commits.map((c) => (
              <li key={c.sha} className="flex items-center gap-2">
                <Avatar c={c.author} size={16} />
                <span className="min-w-0 flex-1 truncate text-foreground">{c.message}</span>
                <Oct name="check" size={14} className="shrink-0 text-[var(--gh-open)]" />
                <code className="shrink-0 font-mono text-[12px]">{c.sha}</code>
              </li>
            ))}
          </ul>
        </TimelineEvent>
      );
    case 'labeled':
      return (
        <TimelineEvent ui={ui} icon="tag">
          {who(item.author)} added {item.labels.map((l) => <LabelChip key={l.name} label={l} dark={ui.dark} className="mx-0.5 align-[1px]" />)} labels {item.when}
        </TimelineEvent>
      );
    case 'requested':
      return <TimelineEvent ui={ui} icon="eye">{who(item.author)} requested a review from <b className="font-semibold text-foreground">{item.reviewer.login}</b> {item.when}</TimelineEvent>;
    case 'review':
      return (
        <>
          <TimelineEvent ui={ui} icon={item.state === 'approved' ? 'check' : 'eye'} badge={item.state === 'approved' ? 'bg-(--gh-merge) text-white' : undefined}>
            {who(item.author)} {item.state === 'approved' ? 'approved these changes' : 'reviewed'} {item.when}
          </TimelineEvent>
          {item.body ? <CommentCard ui={ui} author={item.author} when={item.when} body={item.body} verb="left a comment" role="Member" /> : null}
        </>
      );
  }
}

export function MergeBox({ ui }: { ui: Layout }) {
  const row = (icon: ReactNode, title: string, text: string) => (
    <div className="flex items-start gap-3 border-b border-border px-4 py-3">
      {icon}
      <div className="min-w-0">
        <div className="font-semibold">{title}</div>
        <div className="text-[12px] text-muted-foreground">{text}</div>
      </div>
    </div>
  );
  const ok = <span className="grid size-8 shrink-0 place-items-center rounded-full bg-(--gh-merge) text-white"><Oct name="check" /></span>;
  return (
    <div className="relative flex gap-4 pt-4">
      {!ui.phone ? <span className="grid size-10 shrink-0 place-items-center rounded-md bg-(--gh-merge) text-white"><Oct name="pr" size={20} /></span> : null}
      <div className="relative z-1 min-w-0 flex-1 overflow-hidden rounded-md border border-(--gh-merge)/60 bg-background">
        {row(ok, 'Changes approved', '1 approving review by reviewers with write access.')}
        {row(ok, 'All checks have passed', `${PR_CHECKS.length} successful checks`)}
        <div className="border-b border-border bg-muted">
          {PR_CHECKS.map((c) => (
            <div key={c.name} className="flex items-center gap-2 px-4 py-1.5 text-[12px] sm:pl-[60px]">
              <Oct name="check" size={14} className="text-[var(--gh-open)]" />
              <b className="min-w-0 truncate font-semibold">{c.name}</b>
              <span className="text-muted-foreground">Successful in {c.time}</span>
            </div>
          ))}
        </div>
        {row(ok, 'No conflicts with base branch', 'Merging can be performed automatically.')}
        <div className="flex flex-wrap items-center gap-3 bg-background px-4 py-3">
          <div className="flex">
            <Button className={cn(ghButton(true), 'rounded-r-none')}>Merge pull request</Button>
            <Button aria-label="Merge options" className={cn(ghButton(true), 'rounded-l-none border-l-white/30 px-2')}><Oct name="chevDown" size={12} /></Button>
          </div>
          <span className="text-[12px] text-muted-foreground">You can also merge this with the command line.</span>
        </div>
      </div>
    </div>
  );
}

/* ── Commits / Checks / Files changed ── */

export function CommitList({ ui }: { ui: Layout }) {
  return (
    <div className={cn('relative', !ui.phone && 'pl-8')}>
      <div className="mb-2 flex items-center gap-2 text-muted-foreground"><Oct name="commit" />Commits on Sep 24, 2026</div>
